bool _isHangulSyllableCodeUnit(int codeUnit) {
  return codeUnit >= 0xAC00 && codeUnit <= 0xD7A3;
}

bool _hasKoreanFinalConsonant(String text) {
  final trimmed = text.trim();
  if (trimmed.isEmpty) return false;
  final codeUnit = trimmed.runes.last;
  if (!_isHangulSyllableCodeUnit(codeUnit)) return false;
  return (codeUnit - 0xAC00) % 28 != 0;
}

/// 이름 + 이/가 (비한글 마지막 글자는 `가` fallback).
String _petNameWithSubjectParticle(String name) {
  final trimmed = name.trim();
  if (trimmed.isEmpty) return trimmed;
  final codeUnit = trimmed.runes.last;
  if (!_isHangulSyllableCodeUnit(codeUnit)) return '$trimmed가';
  return _hasKoreanFinalConsonant(trimmed) ? '$trimmed이' : '$trimmed가';
}

/// 이름 + 은/는 (비한글 마지막 글자는 `는` fallback).
String _petNameWithTopicParticle(String name) {
  final trimmed = name.trim();
  if (trimmed.isEmpty) return trimmed;
  final codeUnit = trimmed.runes.last;
  if (!_isHangulSyllableCodeUnit(codeUnit)) return '$trimmed는';
  return _hasKoreanFinalConsonant(trimmed) ? '$trimmed은' : '$trimmed는';
}

